let balls = [];
let blocks = [];
let rects = [];
let colors = ['#1A53C0', '#d63230', "#f5d547", '#0D274B', "#ffffff"];
let SEED = Math.floor(Math.random() * 10000);

function setup() {
  createCanvas(700, 700);
  rectMode(CENTER);
  colorMode(HSB, 360, 100, 100, 100);
  let centerX = width / 2;
  let centerY = height / 2;
  randomSeed(SEED);
  divideRect(centerX, centerY, width * 0.75, height * 0.75, 8, rects);

  for (let r of rects) {
    let clr = random(colors);
    blocks.push(new Block(r.x, r.y, r.w, r.h, clr));
  }

  for (let i = 0; i < 1; i++) {
    let clr = random(colors);
    let d = 0.01 * width;
    balls.push(new Ball(width * 0.1, height * 0.1, d, clr));
  }
  balls[0].vx = 2;
  balls[0].vy = 2;
}

function draw() {
  background('#fdfaf8');
  for (let ball of balls) {
    ball.update();
    ball.show();
  }
  for (let block of blocks) {
    block.show();
  }
  CollisionManager.handleCollisions(balls, blocks);
}

function divideRect(x, y, w, h, n, arr) {
  n--;
  if (n >= 0) {
    let w1 = w * random(0.2, 0.8);
    let h1 = h * random(0.2, 0.8);
    let w2 = w - w1;
    let h2 = h - h1;
    let rnd = 1;
    if (rnd == 0) {
      divideRect(x - (w / 2) + (w1 / 2), y - (h / 2) + (h1 / 2), w1, h1, n, arr);
      divideRect(x + (w / 2) - (w2 / 2), y - (h / 2) + (h1 / 2), w2, h1, n, arr);
      divideRect(x + (w / 2) - (w2 / 2), y + (h / 2) - (h2 / 2), w2, h2, n, arr);
      divideRect(x - (w / 2) + (w1 / 2), y + (h / 2) - (h2 / 2), w1, h2, n, arr);
    } else {
      if (w > h) {
        divideRect(x - (w / 2) + (w1 / 2), y, w1, h, n, arr);
        divideRect(x + (w / 2) - (w2 / 2), y, w2, h, n, arr);
      } else {
        divideRect(x, y - (h / 2) + (h1 / 2), w, h1, n, arr);
        divideRect(x, y + (h / 2) - (h2 / 2), w, h2, n, arr);
      }
    }
  } else {
    arr.push({ x: x, y: y, w: w, h: h });
  }
}

class Ball {
  constructor(x, y, d, clr) {
    this.x = x;
    this.y = y;
    this.d = d;
    this.r = d / 2;
    this.vx = random(-1, 1) * 2;
    this.vy = random(-1, 1) * 2;
    this.clr = clr;
  }

  show() {
    fill(this.clr);
    ellipse(this.x, this.y, this.d);
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
  }
}

class Block {
  constructor(x, y, w, h, clr) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.clr = clr;
  }

  show() {
    fill(this.clr);
    rect(this.x, this.y, this.w, this.h);
  }
}

class CollisionManager {
  static handleCollisions(balls, blocks) {
    for (let ball of balls) {
      if (ball.x - ball.r < 0) {
        ball.vx *= -1;
        ball.x = ball.r;
      } else if (ball.x + ball.r > width) {
        ball.vx *= -1;
        ball.x = width - ball.r;
      }
      if (ball.y - ball.r < 0) {
        ball.vy *= -1;
        ball.y = ball.r;
      } else if (ball.y + ball.r > height) {
        ball.vy *= -1;
        ball.y = height - ball.r;
      }
    }

    for (let i = 0; i < balls.length; i++) {
      for (let j = i + 1; j < balls.length; j++) {
        let ball1 = balls[i];
        let ball2 = balls[j];
        if (this.checkBallBallCollision(ball1, ball2)) {
          this.resolveBallBallCollision(ball1, ball2);
        }
      }
    }

    for (let ball of balls) {
      for (let i = blocks.length - 1; i >= 0; i--) {
        let block = blocks[i];
        if (this.checkBallBlockCollision(ball, block)) {
          let dx = ball.x - block.x;
          let dy = ball.y - block.y;
          let absDx = abs(dx);
          let absDy = abs(dy);
          if (absDx > absDy) {
            ball.vx *= -1;
          } else {
            ball.vy *= -1;
          }
          let newD = 0.01 * width;
          let newBall = new Ball(ball.x, ball.y, newD, block.clr);
          balls.push(newBall);
          blocks.splice(i, 1);
        }
      }
    }
  }

  static checkBallBallCollision(ball1, ball2) {
    let dx = ball2.x - ball1.x;
    let dy = ball2.y - ball1.y;
    let distance = sqrt(dx * dx + dy * dy);
    return distance < (ball1.r + ball2.r);
  }

  static resolveBallBallCollision(ball1, ball2) {
    let dx = ball2.x - ball1.x;
    let dy = ball2.y - ball1.y;
    let distance = sqrt(dx * dx + dy * dy);
    if (distance === 0) return;

    let nx = dx / distance;
    let ny = dy / distance;

    let tx = -ny;
    let ty = nx;

    let v1n = ball1.vx * nx + ball1.vy * ny;
    let v1t = ball1.vx * tx + ball1.vy * ty;
    let v2n = ball2.vx * nx + ball2.vy * ny;
    let v2t = ball2.vx * tx + ball2.vy * ty;

    ball1.vx = v2n * nx + v1t * tx;
    ball1.vy = v2n * ny + v1t * ty;
    ball2.vx = v1n * nx + v2t * tx;
    ball2.vy = v1n * ny + v2t * ty;

    let overlap = (ball1.r + ball2.r) - distance;
    if (overlap > 0) {
      let correction = overlap / 2;
      ball1.x -= correction * nx;
      ball1.y -= correction * ny;
      ball2.x += correction * nx;
      ball2.y += correction * ny;
    }
  }

  static checkBallBlockCollision(ball, block) {
    let left = block.x - block.w / 2;
    let right = block.x + block.w / 2;
    let top = block.y - block.h / 2;
    let bottom = block.y + block.h / 2;
    return (
      ball.x + ball.r > left &&
      ball.x - ball.r < right &&
      ball.y + ball.r > top &&
      ball.y - ball.r < bottom
    );
  }
}

